import React from 'react';

import { getEmptyClub } from '@apps/Clubs/@mappers/clubs.empty.mapper';
import { getOneClubAsync } from '@apps/Clubs/@services/clubs.service';
import { IClub } from '@apps/Clubs/@types/clubs.types';
import { ClubEdit } from '@apps/Clubs/components/ClubEdit';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

interface IClubsAddPageProps {
  id?: number;
}

const ClubsAddPage: React.FC<IClubsAddPageProps> = ({ id }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IClub>();
  const [err, setErr] = React.useState<string | undefined>(undefined);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);

        const d = id ? await getOneClubAsync(id) : getEmptyClub();
        setData(d);
      } catch (e) {
        setErr((e as Error).message);
      } finally {
        setIsLoading(false);
      }
    };

    init();
  }, [id]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err}</PohAlert>;
  }

  if (!data) {
    return <PohAlert>No data</PohAlert>;
  }

  return (
    <div>
      <Breadcrumb
        data={
          [
            { href: '/clubs', text: 'Клубы' },
            id && data && { href: `/clubs/${id}`, text: data.name },
            id && { href: `/clubs/${id}/edit`, text: 'Редактирование', active: true },
            !id && { href: `/clubs/add`, text: 'Добавление', active: true },
          ].filter(Boolean) as any
        }
      />
      <PohContainer>
        <PageHeader title={data?.name || 'Новый клуб'}></PageHeader>
        <PohRow>
          <PohCol sm={12}>
            <ClubEdit
              club={data}
              onSave={(d) => {
                notificationHelper.success(data.id > 0 ? 'Клуб Обновлен' : 'Клуб добавлен');
                setData(d);
              }}
            />
          </PohCol>
        </PohRow>
      </PohContainer>
    </div>
  );
};

export default ClubsAddPage;
