import React from 'react';

import { addOrEditClubAsync } from '@apps/Clubs/@services/clubs.service';
import { IClub } from '@apps/Clubs/@types/clubs.types';
import GeoRegionSelectInput from '@components/GeoRegionSelector/GeoRegionSelectInput';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohButton from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

import ClubSelectInput from '../ClubSelectInput';

interface IClubEditProps {
  club: IClub;
  onSave: (up: IClub) => void;
}

export const ClubEdit: React.FC<IClubEditProps> = ({ club, onSave }) => {
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IClub>(club);

  const handleChange =
    <k extends keyof IClub>(fieldName: k) =>
    (value: IClub[k]) =>
      setData((cur) => ({ ...cur, [fieldName]: value }));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setIsLoading(true);

      const id = await addOrEditClubAsync(data);
      onSave({ ...data, id });
    } catch (error) {
      setErr(error as Error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="vertical-gapped">
      <PohInput
        label="Сокращенное название"
        placeholder="Походники"
        required
        name="club_name"
        autoComplete="club_name"
        horizontal
        value={data.name}
        onChange={handleChange('name')}
        maxLength={128}
        disabled={isLoading}
      />

      <PohInput
        label="Полное название"
        placeholder="Самоорганизованная группа туристов Походники Пензы"
        required
        name="club_full_name"
        autoComplete="club_full_name"
        horizontal
        value={data.full_name}
        onChange={handleChange('full_name')}
        maxLength={512}
        disabled={isLoading}
      />
      <PohInput
        label="Описание"
        type={InputTypes.textarea}
        name="club_description"
        autoComplete="club_description"
        horizontal
        value={data.description}
        onChange={handleChange('description')}
        disabled={isLoading}
      />
      <PohInput
        label="Ссылка на страницу клуба в интернете"
        required
        name="club_link"
        autoComplete="club_link"
        horizontal
        value={data.link}
        onChange={handleChange('link')}
        maxLength={255}
        disabled={isLoading}
        placeholder={location.origin}
      />

      <PohInput
        label="Ссылка на логотип (Маленький, до 200*200)"
        required
        name="club_logo"
        autoComplete="club_logo"
        horizontal
        value={data.logo}
        onChange={handleChange('logo')}
        maxLength={255}
        disabled={isLoading}
        type={InputTypes.url}
        placeholder={location.origin + '/favicon.svg'}
      />
      <PohInput
        label="Ссылка на логотип большой"
        required
        name="club_logo_full"
        autoComplete="club_logo_full"
        horizontal
        value={data.logo_full}
        onChange={handleChange('logo_full')}
        maxLength={255}
        disabled={isLoading}
        type={InputTypes.url}
        placeholder={location.origin + '/apple-touch-icon.png'}
      />
      <ClubSelectInput
        label="Родительский клуб"
        required
        name="club_parent"
        autoComplete="club_parent"
        horizontal
        value={data.parent}
        onChange={handleChange('parent')}
        disabled={isLoading}
      />
      <GeoRegionSelectInput
        label="Регион"
        required
        name="club_region"
        autoComplete="club_region"
        horizontal
        value={data.geoRegion}
        onChange={handleChange('geoRegion')}
        disabled={isLoading}
      />
      <PohInput
        label="Дата основания"
        name="club_foundation_at"
        autoComplete="club_foundation_at"
        horizontal
        value={data.foundation_at}
        onChange={handleChange('foundation_at')}
        maxLength={128}
        type={InputTypes.date}
        disabled={isLoading}
      />
      <PohInput
        label="Уникальный код"
        placeholder="poh_pnz"
        name="club_code"
        autoComplete="club_code"
        horizontal
        value={data.code}
        onChange={handleChange('code')}
        maxLength={255}
        disabled={isLoading}
      />
      <PohRow>
        <PohCol sm={2}></PohCol>
        <PohCol sm={5}>
          <PohCheckbox
            label="Публичный (кто угодно может присоединиться)"
            checked={data.is_public}
            onChange={handleChange('is_public')}
          />
        </PohCol>
        <PohCol sm={5}></PohCol>
      </PohRow>
      {err && <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>}
      <PohRow>
        <PohCol sm={2} />
        <PohCol sm={10}>
          <PohButton type="submit" disabled={isLoading}>
            Сохранить
          </PohButton>
        </PohCol>
      </PohRow>
    </form>
  );
};

export const editClubInModalAsync = (club: IClub): Promise<IClub> => {
  return new Promise((res) => {
    showModal({
      title: club.id > 0 ? 'Редактирование клуба' : 'Создание клуба',
      children: (clos) => (
        <ClubEdit
          club={club}
          onSave={(up) => {
            res(up);
            clos();
          }}
        />
      ),
    });
  });
};
